"""Select received purchase history and browse its source-linked lines."""
HTML='''<section class="card files-section"><h2>USAR COMPRAS HISTÓRICAS RECIBIDAS</h2><p id="selected-purchases-company"></p><p id="selected-purchases-current"></p><details><summary>Seleccionar archivos y revisar las últimas compras</summary><p>Recibe primero tu Excel o CSV como Líneas de facturas de compra. En Expedientes recibidos, marca solo los archivos de compras de esta empresa ficticia y corte. Usa códigos exactos de proveedor y SKU del catálogo activo.</p><button id="selected-purchases-preview" type="button">Comprobar las compras marcadas</button><div id="selected-purchases-review" class="files-step" hidden><h3>LÍNEAS PROPUESTAS · SIN UTILIZAR TODAVÍA</h3><p id="selected-purchases-summary"></p><div id="selected-purchases-rows" class="scroll"></div><p>La selección sustituye la selección recibida anterior completa y se consulta junto a los documentos originales. Incluye todas las partes que quieras mantener. Las facturas ya presentes en los documentos originales y las líneas repetidas se bloquean. No se crean facturas fiscales, existencias, pagos ni vencimientos.</p><p>El precio efectivo es el neto de la línea dividido por su cantidad. Las referencias para negociar usan el proveedor de la ficha, la misma unidad y EUR. Si hay varias líneas en la última fecha, no se elige una arbitrariamente. Las compras a otros proveedores se consultan en Compras y Stock.</p></div><div class="fields"><label>Responsable<input id="selected-purchases-actor" maxlength="500"></label><label>Motivo<input id="selected-purchases-reason" maxlength="500"></label></div><label><input id="selected-purchases-ack" type="checkbox" style="display:inline;width:auto"> He revisado las líneas, sus referencias y su fecha. Se utilizarán como historial recibido al corte, sin acreditar pago ni recepción.</label><div class="files-actions"><button id="selected-purchases-commit" type="button" class="primary" disabled>Usar este historial en las propuestas</button><button id="selected-purchases-clear" type="button" disabled>Retirar el historial recibido seleccionado</button></div></details><p id="selected-purchases-notice" class="files-notice" role="status"></p></section>'''
PURCHASE_HTML='''<section class="card"><h2>COMPRAS · LÍNEAS RECIBIDAS SELECCIONADAS</h2><p id="received-purchases-scope"></p><label>Buscar factura, proveedor, SKU o archivo<input id="received-purchases-query" type="search"></label><p id="received-purchases-count" role="status"></p><div id="received-purchases-lines" class="scroll"></div><div class="files-actions"><button id="received-purchases-prev" type="button">Anterior</button><button id="received-purchases-next" type="button">Siguiente</button></div></section>'''
JS=r'''
let selectedPurchasesTicket=null,selectedPurchasesSequence=0,selectedPurchasesBusy=false,receivedPurchasesPage=0;
function invalidateSelectedPurchases(){selectedPurchasesSequence++;selectedPurchasesTicket=null;$('selected-purchases-ack').checked=false;$('selected-purchases-review').hidden=true;$('selected-purchases-commit').disabled=true}
function purchaseReceivedTable(target,lines){receptionTable(target,['Factura / fecha','Proveedor','SKU','Cantidad / unidad','Neto de línea','Precio neto / unidad','Archivo / fila'],lines.map(l=>[l.invoice_number+' · '+stockDate(l.issue_date),l.supplier_name+' / '+l.supplier_id,l.article_id,stockNumber(l.quantity)+' '+l.unit,money(l.net_amount)+' EUR',money(l.effective_net_unit_price)+' EUR',l.source_refs.map(s=>s.filename+' · fila '+s.row).join(' · ')]));[...$(target).querySelectorAll('tbody tr')].forEach((row,index)=>addArticleStockLink(row.children[2],lines[index].article_id))}
function renderSelectedPurchases(){invalidateSelectedPurchases();const s=state.selected_purchase_history;$('selected-purchases-company').textContent='Empresa activa: '+(state.info.company.legal_name||state.info.company.company_id)+' · corte '+stockDate(state.info.as_of_date);$('selected-purchases-current').textContent=s?s.message:'Sin líneas recibidas seleccionadas; se conserva el historial documental original.';$('selected-purchases-clear').disabled=!s||s.status==='CLEARED';$('received-purchases-scope').textContent=s?s.message:'Recibe y selecciona líneas de compra desde Carga de archivos para consultarlas aquí.';receivedPurchasesPage=0;$('received-purchases-query').value='';filterReceivedPurchases()}
function filterReceivedPurchases(){const query=$('received-purchases-query').value.trim().toLocaleLowerCase('es'),rows=(state.received_purchase_lines||[]).filter(l=>!query||[l.invoice_number,l.supplier_name,l.supplier_id,l.article_id,...l.source_refs.map(s=>s.filename)].join(' ').toLocaleLowerCase('es').includes(query));receivedPurchasesPage=Math.max(0,Math.min(receivedPurchasesPage,Math.ceil(rows.length/100)-1));const page=rows.slice(receivedPurchasesPage*100,(receivedPurchasesPage+1)*100);purchaseReceivedTable('received-purchases-lines',page);$('received-purchases-count').textContent='Mostrando '+page.length+' de '+rows.length+' líneas · página '+(receivedPurchasesPage+1)+' de '+Math.max(1,Math.ceil(rows.length/100));$('received-purchases-prev').disabled=receivedPurchasesPage===0;$('received-purchases-next').disabled=(receivedPurchasesPage+1)*100>=rows.length}
$('received-purchases-query').addEventListener('input',()=>{receivedPurchasesPage=0;filterReceivedPurchases()});$('received-purchases-prev').onclick=()=>{receivedPurchasesPage--;filterReceivedPurchases()};$('received-purchases-next').onclick=()=>{receivedPurchasesPage++;filterReceivedPurchases()};
$('selected-purchases-ack').onchange=()=>{$('selected-purchases-commit').disabled=!selectedPurchasesTicket||!$('selected-purchases-ack').checked};
$('selected-purchases-preview').onclick=async()=>{invalidateSelectedPurchases();const sequence=selectedPurchasesSequence,dataset=$('dataset').value,batch_ids=[...$('received-batches').querySelectorAll('input:checked')].map(x=>x.value);selectedPurchasesBusy=true;$('selected-purchases-preview').disabled=true;$('selected-purchases-notice').textContent='Comprobando referencias, facturas y posibles duplicados…';try{const r=await api('/api/purchase-history/preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,batch_ids})});if(sequence!==selectedPurchasesSequence||dataset!==$('dataset').value)return;selectedPurchasesTicket=r.ticket;$('selected-purchases-review').hidden=false;$('selected-purchases-summary').textContent=r.files.join(' · ')+' · '+r.line_count+' líneas · '+r.non_primary_supplier_lines+' de proveedores distintos del indicado en la ficha · '+r.error_count+' errores. Mostrando '+r.sample.length+' líneas.'+(r.replaces_previous_selection?' Sustituye la selección recibida anterior.':'');purchaseReceivedTable('selected-purchases-rows',r.sample);$('selected-purchases-notice').textContent=r.error_count?r.errors.map(e=>e.filename+' · fila '+e.row+' · '+(e.article_id||'SKU')+': '+e.message).join(' | '):'Revisa las líneas y confirma responsable, motivo y alcance antes de utilizarlas.';$('selected-purchases-commit').disabled=!r.ticket||!$('selected-purchases-ack').checked}catch(e){if(sequence===selectedPurchasesSequence)$('selected-purchases-notice').textContent=e.message}finally{selectedPurchasesBusy=false;$('selected-purchases-preview').disabled=false}};
async function changeSelectedPurchases(clear){if(selectedPurchasesBusy||(!clear&&!selectedPurchasesTicket))return;const dataset=$('dataset').value,sequence=selectedPurchasesSequence;selectedPurchasesBusy=true;$('selected-purchases-commit').disabled=true;$('selected-purchases-clear').disabled=true;try{const r=await api(clear?'/api/purchase-history/clear':'/api/purchase-history/commit',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,ticket:selectedPurchasesTicket,actor:$('selected-purchases-actor').value,reason:$('selected-purchases-reason').value,acknowledge_references:$('selected-purchases-ack').checked})});if(dataset!==$('dataset').value||sequence!==selectedPurchasesSequence)return;await refresh();$('selected-purchases-notice').textContent=clear?'Selección retirada. Se recupera el historial documental original; las propuestas guardadas conservan sus referencias.':r.status==='UNCHANGED'?'Ese historial ya estaba seleccionado. No se ha duplicado.':'Historial recibido seleccionado. Consulta las líneas en Compras y las referencias comparables en las propuestas. Existencias y tesorería permanecen iguales.'}catch(e){if(dataset===$('dataset').value)$('selected-purchases-notice').textContent=e.message}finally{selectedPurchasesBusy=false;$('selected-purchases-commit').disabled=!selectedPurchasesTicket||!$('selected-purchases-ack').checked;$('selected-purchases-clear').disabled=!state.selected_purchase_history||state.selected_purchase_history.status==='CLEARED'}}
$('selected-purchases-commit').onclick=()=>changeSelectedPurchases(false);$('selected-purchases-clear').onclick=()=>changeSelectedPurchases(true);
'''
